(function(root,factory){if(typeof module==='object')module.exports=factory();else root.DirtEngine=factory()})(typeof window==='object'?window:this,()=>{
const learning=()=>typeof ArcadeLearning!=='undefined'?ArcadeLearning:(typeof window!=='undefined'?window.ArcadeLearning:null);function recordPractice(owner,correct,timeout=false){const api=learning(),q=owner.question;if(!api?.active||!q||q.completed||owner.practiceAnsweredQuestion===q)return false;owner.practiceAnsweredQuestion=q;api.record(q,correct,undefined,{timeout});return true;}
class Race{
 constructor(o={}){this.random=o.random||Math.random;this.laps=o.laps||3;this.goal=this.laps*8;this.target=o.target||20;this.operation=o.operation||'mul';this.range=o.range||10;this.timed=Number.isFinite(o.sessionSeconds)&&o.sessionSeconds>0;this.duration=this.timed?o.sessionSeconds:this.goal/this.target*60;if(this.timed){this.goal=this.duration*this.target/60;this.laps=this.goal/8;}this.active=true;this.elapsed=0;this.correct=0;this.attempts=0;this.streak=0;this.charge=0;this.coins=0;this.boost=0;this.playerDistance=0;this.paceDistance=0;this.targetDistance=0;this.speed=0;this.paceSpeed=this.target/60/8;this.ready=true;this.cooldown=0;this.questionElapsed=0;this.won=null;this.events=[];this.question=o.deferQuestion?null:this.makeQuestion();this.lastLap=0;this.lastCorrectAt=0;this.rhythm=this.target/60;}
 revealQuestion(){if(!this.question&&this.active){this.question=this.makeQuestion();this.questionElapsed=0;}return this.question;}
 makeQuestion(){if(learning()?.active)return learning().next();const a=1+Math.floor(this.random()*this.range),b=1+Math.floor(this.random()*this.range),op=this.operation==='mix'?['add','sub','mul','div'][Math.floor(this.random()*4)]:this.operation;const answer=op==='add'?a+b:op==='mul'?a*b:b,text=op==='add'?`${a} + ${b}`:op==='mul'?`${a} × ${b}`:op==='sub'?`${a+b} − ${a}`:`${a*b} ÷ ${a}`;const values=new Set([answer]);for(const n of [answer+1,answer-1,answer+a,answer+b,answer+2,answer-2])if(n>=0&&values.size<4)values.add(n);while(values.size<4)values.add(answer+values.size);const choices=[...values];for(let i=3;i>0;i--){const j=Math.floor(this.random()*(i+1));[choices[i],choices[j]]=[choices[j],choices[i]]}return{text,answer,choices}}
 answer(value,timeout=false){if(!this.question||this.question.completed||!this.active||!this.ready)return{accepted:false};timeout=timeout||this.questionElapsed>=3-1e-9;if(timeout)value=null;this.ready=false;this.cooldown=.25;this.attempts++;const ok=value===this.question.answer;recordPractice(this,ok,timeout);if(ok){this.correct++;this.streak++;this.charge++;this.coins+=25;this.targetDistance=this.correct/8;const interval=Math.max(.4,this.elapsed-this.lastCorrectAt);this.rhythm=this.rhythm*.55+(1/interval)*.45;this.lastCorrectAt=this.elapsed;const power=this.charge===4;if(power){this.charge=0;this.boost=2;}this.events.push({type:'correct',coins:25,power,correct:this.correct});if(!this.timed&&this.correct>=this.goal)this.finish(true)}else{this.streak=0;this.charge=0;this.events.push({type:'wrong',answer:this.question.answer,text:this.question.text,timeout})}return{accepted:true,correct:ok}}
 update(dt){if(!Number.isFinite(dt)||dt<=0||!this.active||!this.question)return;const exposedQuestion=this.question;let remaining=Math.min(dt,this.duration-this.elapsed);while(remaining>1e-9&&this.active){const step=Math.min(.02,remaining);remaining-=step;this.elapsed+=step;this.paceDistance=this.timed?this.elapsed*this.paceSpeed:Math.min(this.laps,this.elapsed*this.paceSpeed);this.boost=Math.max(0,this.boost-step);if(!this.ready){this.cooldown-=step;if(this.cooldown<=1e-9){this.ready=true;this.question=this.makeQuestion();this.questionElapsed=0}}else if(this.question===exposedQuestion){this.questionElapsed+=step;if(this.questionElapsed>=3-1e-9)this.answer(null,true)}const gap=Math.max(0,this.targetDistance-this.playerDistance),desired=Math.min(gap*4,this.rhythm/8*(this.boost>0?1.65:1)+gap*1.1);this.speed+=(desired-this.speed)*(1-Math.exp(-step*5));const advance=Math.min(gap,Math.max(0,this.speed)*step);this.playerDistance+=advance;if(advance===gap)this.speed=0;const completed=Math.floor(this.playerDistance+1e-8);while(completed>this.lastLap&&this.lastLap<this.laps){this.lastLap++;this.events.push({type:'lap',lap:this.lastLap})}if(this.elapsed+1e-9>=this.duration)this.finish(this.timed?this.gap>=0:false)}}
 finish(won){if(!this.active)return;if(!won&&!this.timed)recordPractice(this,false,true);this.active=false;this.won=won;this.events.push({type:'finish',won})}
 get questionRemaining(){return Math.max(0,3-this.questionElapsed)}get gap(){return this.correct-this.elapsed*this.target/60}get progress(){return Math.min(1,this.playerDistance/this.laps)}get remaining(){return Math.max(0,this.duration-this.elapsed)}drain(){const events=this.events;this.events=[];return events}
}return{Race}});
